=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements interface_spec.md per microarchitecture.md:
//   - zero wait states (pready tied high), no state machine
//   - access = psel && penable is the only cycle that acts
//   - mapped = word aligned and offset 0x0..0xC; otherwise PSLVERR
//   - prdata/pslverr are zero outside the access phase
//   - synchronous, active-low reset clears all registers
module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam integer NBYTES = DATA_WIDTH / 8;

    // Access phase: the one cycle in which the response is sampled and a
    // write takes effect.
    wire access = psel & penable;

    // Address decode: word aligned and inside 0x0..0xC.
    wire mapped = (~|paddr[1:0]) & (~|paddr[ADDR_WIDTH-1:4]);

    wire [1:0] idx = paddr[3:2];

    wire wr_en = access & pwrite & mapped;
    wire rd_en = access & ~pwrite & mapped;

    // Byte-enable mask expanded from pstrb.
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < NBYTES; g = g + 1) begin : g_wmask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // Register file: four separate flop registers.
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (wr_en) begin
            case (idx)
                2'd0: reg0 <= (reg0 & ~wmask) | (pwdata & wmask);
                2'd1: reg1 <= (reg1 & ~wmask) | (pwdata & wmask);
                2'd2: reg2 <= (reg2 & ~wmask) | (pwdata & wmask);
                2'd3: reg3 <= (reg3 & ~wmask) | (pwdata & wmask);
            endcase
        end
    end

    // Read data: combinational 4:1 mux, forced to zero unless this is a
    // mapped read access.
    wire [DATA_WIDTH-1:0] rd_mux = (idx == 2'd0) ? reg0 :
                                   (idx == 2'd1) ? reg1 :
                                   (idx == 2'd2) ? reg2 :
                                                   reg3;

    assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access & ~mapped;

`ifdef FORMAL
    // Design-intent assertions (not proven in this submission).
    always @(*) begin
        assert (pready == 1'b1);
        if (!access) assert ((prdata == {DATA_WIDTH{1'b0}}) && (pslverr == 1'b0));
        if (access && !mapped) assert ((pslverr == 1'b1) && (prdata == {DATA_WIDTH{1'b0}}));
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns/1ps
`default_nettype none

// Self-checking directed testbench for apb_regs.
// Inputs are driven 1 ns after the falling edge; outputs are sampled 1 ns
// later, well before the next rising edge, so there is no race with the DUT.
module apb_regs_tb;

    reg         pclk = 1'b0;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed;
    integer failed;
    integer xfer;

    reg [31:0]     model [0:3];
    reg [8*64-1:0] nonce;

    always #5 pclk = ~pclk;

    apb_regs #(.ADDR_WIDTH(8), .DATA_WIDTH(32)) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    // Independent reference decode and strobe mask (not shared with the DUT).
    function is_mapped(input [7:0] a);
        begin
            is_mapped = (a == 8'h00) || (a == 8'h04) || (a == 8'h08) || (a == 8'h0C);
        end
    endfunction

    function [31:0] strb_mask(input [3:0] s);
        begin
            strb_mask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
        end
    endfunction

    task chk1(input got, input exp, input [31:0] tag);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("xfer %0d %s: got %b, expected %b", xfer, tag, got, exp);
            end
        end
    endtask

    task chk32(input [31:0] got, input [31:0] exp, input [31:0] tag);
        begin
            if (got === exp) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("xfer %0d %s: got 0x%08h, expected 0x%08h", xfer, tag, got, exp);
            end
        end
    endtask

    task quiet(input [31:0] tag);
        begin
            chk32(prdata, 32'h0000_0000, tag);
            chk1(pslverr, 1'b0, tag);
        end
    endtask

    task drive_idle;
        begin
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
        end
    endtask

    task idle(input integer n);
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                #1;
                drive_idle;
                #1;
                chk1(pready, 1'b1, "RDYI");
                quiet("IDLE");
            end
        end
    endtask

    task do_reset(input integer n);
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                #1;
                presetn = 1'b0;
                drive_idle;
                #1;
                chk1(pready, 1'b1, "RDYZ");
                quiet("RSTQ");
            end
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
            @(negedge pclk);
            #1;
            presetn = 1'b1;
            #1;
            quiet("RELQ");
        end
    endtask

    task apb_write(input [7:0] a, input [31:0] d, input [3:0] s);
        reg exp_err;
        begin
            exp_err = !is_mapped(a);
            xfer = xfer + 1;
            // setup phase
            @(negedge pclk);
            #1;
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = a;
            pwdata  = d;
            pstrb   = s;
            #1;
            quiet("SETW");
            // access phase
            @(negedge pclk);
            #1;
            penable = 1'b1;
            #1;
            chk1(pready, 1'b1, "RDYW");
            chk1(pslverr, exp_err, "ERRW");
            // the write takes effect on the rising edge that ends this phase
            if (!exp_err)
                model[a[3:2]] = (model[a[3:2]] & ~strb_mask(s)) | (d & strb_mask(s));
        end
    endtask

    task apb_read_exp(input [7:0] a, input [31:0] exp_data);
        reg exp_err;
        begin
            exp_err = !is_mapped(a);
            xfer = xfer + 1;
            // setup phase
            @(negedge pclk);
            #1;
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = a;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
            #1;
            quiet("SETR");
            // access phase
            @(negedge pclk);
            #1;
            penable = 1'b1;
            #1;
            chk1(pready, 1'b1, "RDYR");
            chk1(pslverr, exp_err, "ERRR");
            chk32(prdata, exp_data, "DATR");
        end
    endtask

    task apb_read(input [7:0] a);
        reg [31:0] e;
        begin
            if (is_mapped(a)) e = model[a[3:2]];
            else              e = 32'h0000_0000;
            apb_read_exp(a, e);
        end
    endtask

    task check_all_regs;
        begin
            apb_read(8'h00);
            apb_read(8'h04);
            apb_read(8'h08);
            apb_read(8'h0C);
        end
    endtask

    // Watchdog: a hung run fails instead of running forever.
    initial begin
        #200000;
        $fatal(1, "watchdog: simulation did not finish");
    end

    initial begin
        passed = 0;
        failed = 0;
        xfer   = 0;
        nonce  = {64{8'h00}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {64{8'h00}};

        presetn = 1'b0;
        drive_idle;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;

        // ---- reset and reset values ----
        do_reset(3);
        idle(2);
        apb_read_exp(8'h00, 32'h0000_0000);
        idle(1);
        apb_read_exp(8'h04, 32'h0000_0000);
        idle(2);
        apb_read_exp(8'h08, 32'h0000_0000);
        apb_read_exp(8'h0C, 32'h0000_0000);
        idle(1);

        // ---- full writes, back to back, then read back back to back ----
        apb_write(8'h00, 32'h1234_5678, 4'hF);
        apb_write(8'h04, 32'h9ABC_DEF0, 4'hF);
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h0C, 32'hCAFE_F00D, 4'hF);
        apb_read_exp(8'h00, 32'h1234_5678);
        apb_read_exp(8'h04, 32'h9ABC_DEF0);
        apb_read_exp(8'h08, 32'hDEAD_BEEF);
        apb_read_exp(8'h0C, 32'hCAFE_F00D);
        idle(1);

        // write immediately followed by a read of the same register
        apb_write(8'h08, 32'h0F0F_0F0F, 4'hF);
        apb_read_exp(8'h08, 32'h0F0F_0F0F);
        idle(3);

        // ---- pstrb partial writes ----
        apb_write(8'h00, 32'hAAAA_AAAA, 4'b0001);
        apb_read_exp(8'h00, 32'h1234_56AA);
        apb_write(8'h04, 32'h5555_5555, 4'b0110);
        idle(1);
        apb_read_exp(8'h04, 32'h9A55_55F0);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'b1000);
        apb_read_exp(8'h08, 32'hFF0F_0F0F);
        apb_write(8'h0C, 32'h1111_1111, 4'b0000);   // no byte enabled: no change, no error
        apb_read_exp(8'h0C, 32'hCAFE_F00D);
        apb_write(8'h0C, 32'h2222_2222, 4'b0101);
        apb_read_exp(8'h0C, 32'hCA22_F022);
        apb_write(8'h00, 32'h3333_3333, 4'b1010);
        apb_read_exp(8'h00, 32'h3334_33AA);
        idle(2);

        // ---- PSLVERR: unmapped writes change nothing ----
        apb_write(8'h01, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h02, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h03, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h05, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h0E, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h0F, 32'hFFFF_FFFF, 4'hF);
        idle(1);
        apb_write(8'h10, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h11, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h14, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h40, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h80, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'hF0, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'hFF, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h10, 32'hFFFF_FFFF, 4'h0);
        apb_read_exp(8'h00, 32'h3334_33AA);
        apb_read_exp(8'h04, 32'h9A55_55F0);
        apb_read_exp(8'h08, 32'hFF0F_0F0F);
        apb_read_exp(8'h0C, 32'hCA22_F022);
        idle(1);

        // ---- PSLVERR: unmapped reads return zero ----
        apb_read(8'h01);
        apb_read(8'h02);
        apb_read(8'h03);
        apb_read(8'h06);
        apb_read(8'h0D);
        apb_read(8'h10);
        apb_read(8'h18);
        apb_read(8'h20);
        apb_read(8'h7C);
        apb_read(8'hC0);
        apb_read(8'hFF);
        idle(2);

        // ---- mixed back-to-back mapped and unmapped transfers ----
        apb_write(8'h10, 32'h0BAD_0BAD, 4'hF);
        apb_read(8'h00);
        apb_read(8'h10);
        apb_write(8'h04, 32'h0123_4567, 4'hF);
        apb_read(8'h14);
        apb_read(8'h04);
        apb_write(8'h0A, 32'hFFFF_FFFF, 4'hF);
        apb_read(8'h08);
        idle(1);
        check_all_regs;
        idle(1);

        // ---- reset again ----
        do_reset(2);
        apb_read_exp(8'h00, 32'h0000_0000);
        apb_read_exp(8'h04, 32'h0000_0000);
        apb_read_exp(8'h08, 32'h0000_0000);
        apb_read_exp(8'h0C, 32'h0000_0000);
        idle(1);

        // registers work after the second reset
        apb_write(8'h0C, 32'hA5A5_5A5A, 4'hF);
        apb_read_exp(8'h0C, 32'hA5A5_5A5A);
        apb_read_exp(8'h00, 32'h0000_0000);
        idle(2);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
